#!/usr/bin/env bash
# Engine-free compile check of unreal/Source/Abyssfire (the UE presentation module). No Unreal Engine needed:
# clang++ -fsyntax-only -std=c++20 over every module .cpp (one translation unit per file) against the stub SDK in sdk/,
# with headers generated by the fake UHT in uht/, for Mac editor, Mac game, Android game and iOS shipping; then the
# Build.cs dependency lint and the link scan (unity collisions, undefined / duplicate symbols, exports, platform names).
#   ./run.sh                                  everything; exit 0 only when every file passes in every configuration
#   ./run.sh --only Framework --only Input    a subset (directory, file or header; see --help)
#   ./run.sh --config mac-editor              one configuration (mac-editor, mac-game, android-game, ios-shipping)
#   ./run.sh -j 3 --notes --force             jobs (default 3), compiler notes, ignore the result cache
#   ./run.sh --no-unity                       skip the extra unity translation unit (all passing files together)
#   ./run.sh --no-link-scan                   skip the link scan (it is skipped with --only anyway; --link-scan forces it)
#   ./run.sh --selftest                       prove the check bites: planted faults and negative cases, see README.md
#   ./run.sh --msvc-lint                      extra warnings: the clang twins of MSVC warnings UE makes errors on Windows
#   ./run.sh --stdlib libc++                  compile against libc++ (Xcode / NDK; needs libc++-18-dev), see README.md
#   ABYSS_CC_BUILD=/some/dir ./run.sh         build output elsewhere (default: CompileCheck/build, git-ignored)
# Report: <build>/report.json (machine readable), <build>/uht_report.json, <build>/compile_commands.json.
set -euo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
exec python3 "$here/tools/compile_check.py" "$@"
